<script setup lang="ts">import {ElMessage,ElMessageBox} from 'element-plus';import {computed,ref,reactive,watch} from 'vue';import {useRoute} from 'vue-router';import AppLayout from '../layouts/AppLayout.vue';import {api} from '../api/client';import {modules} from '../config/modules'; const route=useRoute(),rows=ref<any[]>([]),total=ref(0),dialog=ref(false),editing=ref<string|null>(null),form=reactive<any>({});const mod=computed(()=>modules.find(x=>x.key===route.params.key)!); async function load(){if(!mod.value)return;const r=await api.get(`/${mod.value.resource}`,{params:{size:100}});rows.value=r.data.data;total.value=r.data.total} function add(){editing.value=null;Object.keys(form).forEach(k=>delete form[k]);for(const f of mod.value.fields)form[f.key]='';dialog.value=true} function edit(r:any){editing.value=r.id;Object.assign(form,r);dialog.value=true} async function save(){const payload={...form};delete payload.id;delete payload.created_at;delete payload.updated_at;if(editing.value)await api.patch(`/${mod.value.resource}/${editing.value}`,payload);else await api.post(`/${mod.value.resource}`,payload);dialog.value=false;await load();ElMessage.success('已保存')} async function del(r:any){await ElMessageBox.confirm('确认删除这条记录？','提示');await api.delete(`/${mod.value.resource}/${r.id}`);await load()} watch(()=>route.params.key,load,{immediate:true});</script>
<template><AppLayout><div class="toolbar"><div><h2 style="margin:0">{{mod?.title}}</h2><span class="muted">{{mod?.desc}} · 共 {{total}} 条</span></div><el-button type="primary" @click="add">新增</el-button></div><div class="card"><el-table :data="rows"><el-table-column v-for="f in mod?.fields.slice(0,6)" :key="f.key" :prop="f.key" :label="f.label" min-width="130" show-overflow-tooltip/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="del(s.row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑':'新增'" width="680"><el-form label-position="top"><div class="grid" style="grid-template-columns:1fr 1fr"><el-form-item v-for="f in mod?.fields" :key="f.key" :label="f.label"><el-input v-model="form[f.key]" :type="f.type==='password'?'password':f.type==='number'?'number':f.type==='date'?'date':f.type==='datetime-local'?'datetime-local':'text'"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></AppLayout></template>
